package br.com.equilibra.commitment.application;
import br.com.equilibra.commitment.api.CommitmentIndicatorDtos; import br.com.equilibra.commitment.domain.*; import br.com.equilibra.commitment.infrastructure.FinancialCommitmentRepository; import br.com.equilibra.shared.api.CurrentUser; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.math.*; import java.time.*; import java.util.*;
@Service public class CommitmentIndicatorService { private final FinancialCommitmentRepository repo; private final CurrentUser current; public CommitmentIndicatorService(FinancialCommitmentRepository r,CurrentUser c){repo=r;current=c;} @Transactional(readOnly=true) public CommitmentIndicatorDtos.Response indicators(CommitmentIndicatorDtos.Filter f){LocalDate ref=f.referenceDate()==null?LocalDate.now():f.referenceDate();LocalDate from=f.from()==null?ref.minusYears(1):f.from();LocalDate to=f.to()==null?ref.plusYears(1):f.to();var all=(f.accountId()==null?repo.pendingBetween(current.id().toString(),from,to):repo.pendingBetweenAccounts(current.id().toString(),from,to,List.of(f.accountId()))).stream().filter(x->f.type()==null||x.getType()==f.type()).toList();var overdue=all.stream().filter(x->x.getDueDate().isBefore(ref)).toList();var today=all.stream().filter(x->x.getDueDate().equals(ref)).toList();var upcoming=all.stream().filter(x->!x.getDueDate().isBefore(ref.plusDays(1))&&!x.getDueDate().isAfter(ref.plusDays(7))).toList();var future=all.stream().filter(x->x.getDueDate().isAfter(ref.plusDays(7))).toList();return new CommitmentIndicatorDtos.Response(ref,7,group(overdue),group(today),group(upcoming),group(future));}private CommitmentIndicatorDtos.Group group(List<FinancialCommitment> xs){BigDecimal expense=xs.stream().filter(x->x.getType()==CommitmentType.EXPENSE).map(FinancialCommitment::getPlannedAmount).reduce(BigDecimal.ZERO,BigDecimal::add);BigDecimal income=xs.stream().filter(x->x.getType()==CommitmentType.INCOME).map(FinancialCommitment::getPlannedAmount).reduce(BigDecimal.ZERO,BigDecimal::add);return new CommitmentIndicatorDtos.Group(xs.size(),xs.stream().filter(x->x.getType()==CommitmentType.EXPENSE).count(),xs.stream().filter(x->x.getType()==CommitmentType.INCOME).count(),expense.add(income),expense,income);}}
